//! Standalone API connections.
//!
//! A *connection* is owned by tarpi, not by SillyTavern: server address,
//! API key and every sampler value live in `~/.config/tarpi/api.yaml` and are
//! edited with `/api` in a chat. When a connection is active, replies are
//! generated by talking straight to the backend; nothing else is contacted.
//!
//! ## Adding a new kind of connection
//!
//! 1. Write a type that implements [`Provider`] (copy `llamacpp.rs`): it lists
//!    its settings as [`ParamDef`]s (the `api` TUI draws them as sliders,
//!    toggles and text fields on its own), builds the request body and reads
//!    the reply stream.
//! 2. Add one line to [`providers`].
//!
//! Nothing else needs to change: the store, the TUI, token counting and the
//! generation loop only talk to the trait.

pub mod llamacpp;

use crate::api::short;
use crate::gen::{GenEvent, GenMsg};
use anyhow::{anyhow, bail, Context, Result};
use serde::{Deserialize, Serialize};
use serde_json::{json, Map, Value};
use std::time::Duration;
use tokio::sync::mpsc::UnboundedSender;

// ------------------------------------------------------------- parameters

/// What kind of control a setting gets in the `api` TUI.
#[derive(Clone, Copy, Debug)]
pub enum ParamKind {
    /// A number on a slider. A whole-number `step` (with a whole `min`)
    /// makes it an integer setting.
    Slider {
        min: f64,
        max: f64,
        step: f64,
        default: f64,
    },
    /// A whole number typed in (no sensible slider range), e.g. a seed.
    Number { default: i64 },
    Toggle { default: bool },
    Text { default: &'static str },
}

/// One setting of a connection kind.
#[derive(Clone, Copy, Debug)]
pub struct ParamDef {
    /// Key in `api.yaml` (and usually in the request body).
    pub key: &'static str,
    pub label: &'static str,
    /// Heading it is listed under in the TUI.
    pub group: &'static str,
    /// One line shown while the setting is selected.
    pub help: &'static str,
    pub kind: ParamKind,
}

impl ParamDef {
    pub fn default_value(&self) -> Value {
        match self.kind {
            ParamKind::Slider { default, .. } => self.snap(default),
            ParamKind::Number { default } => json!(default),
            ParamKind::Toggle { default } => json!(default),
            ParamKind::Text { default } => json!(default),
        }
    }

    /// Slider with whole numbers only.
    pub fn is_int(&self) -> bool {
        match self.kind {
            ParamKind::Slider { min, step, .. } => step.fract() == 0.0 && min.fract() == 0.0,
            _ => false,
        }
    }

    /// Digits after the decimal point a slider shows (from its step).
    pub fn decimals(&self) -> usize {
        match self.kind {
            ParamKind::Slider { step, .. } => {
                for d in 0..=4usize {
                    let scaled = step * 10f64.powi(d as i32);
                    if (scaled - scaled.round()).abs() < 1e-9 {
                        return d;
                    }
                }
                4
            }
            _ => 0,
        }
    }

    /// Clamp `v` to the slider's range, put it on the step grid and make it a
    /// JSON number (integer for whole-number sliders).
    pub fn snap(&self, v: f64) -> Value {
        match self.kind {
            ParamKind::Slider { min, max, step, .. } => {
                let v = v.max(min).min(max);
                let steps = ((v - min) / step).round();
                let mut v = min + steps * step;
                v = v.max(min).min(max);
                if self.is_int() {
                    json!(v.round() as i64)
                } else {
                    let p = 10f64.powi(self.decimals() as i32);
                    json!((v * p).round() / p)
                }
            }
            ParamKind::Number { .. } => json!(v.round() as i64),
            _ => json!(v),
        }
    }

    /// The value as the TUI shows it.
    pub fn format(&self, v: &Value) -> String {
        match self.kind {
            ParamKind::Slider { .. } => {
                let x = v.as_f64().unwrap_or(0.0);
                if self.is_int() {
                    format!("{}", x.round() as i64)
                } else {
                    format!("{:.*}", self.decimals(), x)
                }
            }
            ParamKind::Number { .. } => format!("{}", v.as_f64().unwrap_or(0.0).round() as i64),
            ParamKind::Toggle { .. } => {
                if v.as_bool().unwrap_or(false) {
                    "on".to_string()
                } else {
                    "off".to_string()
                }
            }
            ParamKind::Text { .. } => v.as_str().unwrap_or("").to_string(),
        }
    }
}

/// The stored value of a setting, or its default when it was never set (or
/// has the wrong type, e.g. after a hand edit).
pub fn value_of(params: &Map<String, Value>, d: &ParamDef) -> Value {
    let stored = params.get(d.key);
    let ok = match (d.kind, stored) {
        (ParamKind::Slider { .. }, Some(v)) | (ParamKind::Number { .. }, Some(v)) => v.is_number(),
        (ParamKind::Toggle { .. }, Some(v)) => v.is_boolean(),
        (ParamKind::Text { .. }, Some(v)) => v.is_string(),
        _ => false,
    };
    if ok {
        stored.cloned().unwrap_or(Value::Null)
    } else {
        d.default_value()
    }
}

pub fn text_of(v: &Value) -> String {
    v.as_str().unwrap_or("").to_string()
}

/// `["a", "b"]` typed as JSON -> the strings. Anything else -> nothing.
pub fn json_strings(s: &str) -> Vec<String> {
    serde_json::from_str::<Vec<String>>(s.trim()).unwrap_or_default()
}

// ---------------------------------------------------------------- presets

/// A named set of setting values (`Normal`, `Creative`, ...) that the `api`
/// TUI can apply to a connection in one go. Only the keys listed are touched.
#[derive(Clone, Debug)]
pub struct Preset {
    pub name: &'static str,
    /// One line shown next to the name.
    pub help: &'static str,
    pub values: Vec<(&'static str, Value)>,
}

// --------------------------------------------------------------- provider

/// What the backend said when it was tested.
#[derive(Clone, Debug, Default)]
pub struct Info {
    pub model: String,
    pub n_ctx: Option<i64>,
}

/// One reading of a line of the reply stream.
pub enum Piece {
    Text(String),
    Done,
    Skip,
    Error(String),
}

/// A kind of backend tarpi can talk to. See the module docs for how to add one.
pub trait Provider: Send + Sync {
    /// Short id stored in `api.yaml` (`llamacpp`).
    fn kind(&self) -> &'static str;
    /// Name shown to people (`llama.cpp`).
    fn label(&self) -> &'static str;
    fn default_url(&self) -> &'static str;
    /// The api type the prompt builder knows this backend by.
    fn textgen_type(&self) -> &'static str;
    /// Every setting, in the order the TUI lists them.
    fn params(&self) -> Vec<ParamDef>;
    /// Ready-made sets of settings the TUI offers with `p`. None by default.
    fn presets(&self) -> Vec<Preset> {
        Vec::new()
    }
    /// `(context size, max reply tokens)` from the settings, used to trim the
    /// chat history when the prompt is built.
    fn limits(&self, params: &Map<String, Value>) -> (i64, i64);
    /// Whether replies are streamed.
    fn streaming(&self, params: &Map<String, Value>) -> bool;
    /// Check what a text setting holds (`Err` = a message for the person).
    fn validate_text(&self, _key: &str, _text: &str) -> std::result::Result<(), String> {
        Ok(())
    }

    /// Path the prompt is POSTed to.
    fn generate_path(&self) -> &'static str;
    /// The request body: settings plus the prompt and the stop strings.
    fn build_body(&self, params: &Map<String, Value>, prompt: &str, stop: &[String]) -> Value;
    /// One line of a streamed reply.
    fn parse_stream_line(&self, line: &str) -> Piece;
    /// A reply that was not streamed.
    fn parse_full(&self, body: &Value) -> Option<String>;
    /// An error message inside a JSON body, if there is one.
    fn error_in(&self, body: &Value) -> Option<String>;

    /// Paths tried (in order) to find out whether the backend is up.
    fn info_paths(&self) -> &'static [&'static str];
    fn parse_info(&self, body: &Value) -> Info;
    /// Path and body of a tokenize request, and how to read the count back.
    fn tokenize_request(&self, text: &str) -> (&'static str, Value);
    fn parse_token_count(&self, body: &Value) -> Option<usize>;
}

static LLAMACPP: llamacpp::LlamaCpp = llamacpp::LlamaCpp;

/// Every kind of connection tarpi knows. Add new ones here.
pub fn providers() -> Vec<&'static dyn Provider> {
    vec![&LLAMACPP as &'static dyn Provider]
}

pub fn provider(kind: &str) -> Option<&'static dyn Provider> {
    providers().into_iter().find(|p| p.kind() == kind)
}

// ------------------------------------------------------------ connections

/// One saved connection.
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct Connection {
    pub name: String,
    pub kind: String,
    pub url: String,
    #[serde(default)]
    pub api_key: String,
    /// Only the settings that differ from the defaults need to be here.
    #[serde(default)]
    pub params: Map<String, Value>,
}

impl Connection {
    /// A connection of `kind` with the default address and settings.
    pub fn new(kind: &str, name: &str) -> Option<Connection> {
        let p = provider(kind)?;
        Some(Connection {
            name: name.to_string(),
            kind: kind.to_string(),
            url: p.default_url().to_string(),
            api_key: String::new(),
            params: Map::new(),
        })
    }

    pub fn provider(&self) -> Option<&'static dyn Provider> {
        provider(&self.kind)
    }

    /// The address without a trailing slash (or `/v1`).
    pub fn base(&self) -> String {
        let b = self.url.trim().trim_end_matches('/');
        let b = b.strip_suffix("/v1").unwrap_or(b).trim_end_matches('/');
        match REMOTE_HOST.get() {
            Some(h) => with_remote_host(b, h),
            None => b.to_string(),
        }
    }

    pub fn get(&self, d: &ParamDef) -> Value {
        value_of(&self.params, d)
    }

    pub fn set(&mut self, key: &str, v: Value) {
        self.params.insert(key.to_string(), v);
    }

    /// Every setting with its current value.
    pub fn resolved(&self) -> Map<String, Value> {
        let mut m = Map::new();
        if let Some(p) = self.provider() {
            for d in p.params() {
                m.insert(d.key.to_string(), self.get(&d));
            }
        }
        m
    }
}

/// `~/.config/tarpi/api.yaml`
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct Store {
    /// Name of the connection chats use.
    #[serde(default)]
    pub active: String,
    #[serde(default)]
    pub connections: Vec<Connection>,
}

impl Store {
    /// Read the file; a missing or empty file is an empty store.
    pub fn load() -> Result<Store> {
        let Some(path) = crate::config::api_path() else {
            return Ok(Store::default());
        };
        if !path.exists() {
            return Ok(Store::default());
        }
        let text = std::fs::read_to_string(&path)
            .with_context(|| format!("reading {}", path.display()))?;
        if text.trim().is_empty() {
            return Ok(Store::default());
        }
        serde_yaml::from_str(&text).with_context(|| format!("parsing {}", path.display()))
    }

    pub fn save(&self) -> Result<()> {
        let path = crate::config::api_path()
            .ok_or_else(|| anyhow!("no config directory on this system"))?;
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir)
                .with_context(|| format!("creating {}", dir.display()))?;
        }
        let mut text = String::from(
            "# tarpi API connections. Edited with /api in a chat; hand edits are fine too.\n\
             # `active` names the connection chats use. Settings left out use their defaults.\n",
        );
        text.push_str(&serde_yaml::to_string(self).context("writing api.yaml")?);
        let tmp = path.with_extension("yaml.tmp");
        std::fs::write(&tmp, text).with_context(|| format!("writing {}", tmp.display()))?;
        std::fs::rename(&tmp, &path).with_context(|| format!("writing {}", path.display()))?;
        Ok(())
    }

    /// The connection chats should use, if there is a usable one.
    pub fn active_connection(&self) -> Option<Connection> {
        let c = self
            .connections
            .iter()
            .find(|c| c.name == self.active)
            .or_else(|| if self.active.is_empty() { self.connections.first() } else { None })?;
        c.provider()?;
        Some(c.clone())
    }

    /// A name no other connection has: `base`, `base2`, `base3`, ...
    pub fn unique_name(&self, base: &str) -> String {
        let taken = |n: &str| self.connections.iter().any(|c| c.name == n);
        if !taken(base) {
            return base.to_string();
        }
        let mut i = 2;
        loop {
            let n = format!("{}{}", base, i);
            if !taken(&n) {
                return n;
            }
            i += 1;
        }
    }
}

// ---------------------------------------------------------- settings glue

/// Make the in-memory settings (see `config::base_settings`) say "use this
/// connection", so the prompt builder, which reads those settings, works
/// unchanged: Text Completion, the connection's backend type and address,
/// context size and reply length.
pub fn overlay(settings: &mut Value, c: &Connection) {
    let Some(p) = c.provider() else { return };
    let params = c.resolved();
    let (ctx, gen) = p.limits(&params);
    let ty = p.textgen_type();
    let Some(root) = settings.as_object_mut() else {
        return;
    };
    root.insert("main_api".to_string(), json!("textgenerationwebui"));
    root.insert("max_context".to_string(), json!(ctx));
    root.insert("amount_gen".to_string(), json!(gen));
    let mut urls = Map::new();
    urls.insert(ty.to_string(), json!(c.base()));
    root.insert(
        "textgenerationwebui_settings".to_string(),
        json!({
            "type": ty,
            "server_urls": Value::Object(urls),
            "streaming": p.streaming(&params),
        }),
    );
}

/// A copy of `c` set up for writing a summary (`/summarize`): the reply may be
/// `max_tokens` long and the sampling sticks to the facts (low temperature,
/// nothing that adds variety or punishes names being repeated). The saved
/// connection is not touched. Settings a kind of connection does not have are
/// skipped.
pub fn for_summary(c: &Connection, max_tokens: usize) -> Connection {
    let mut s = c.clone();
    let keys: Vec<&'static str> = match s.provider() {
        Some(p) => p.params().iter().map(|d| d.key).collect(),
        None => Vec::new(),
    };
    let has = |k: &str| keys.iter().any(|x| *x == k);
    let mut set: Vec<(&str, Value)> = vec![
        ("n_predict", json!(max_tokens as i64)),
        ("temperature", json!(0.5)),
        ("repeat_penalty", json!(1.0)),
        ("frequency_penalty", json!(0.0)),
        ("presence_penalty", json!(0.0)),
        ("dry_multiplier", json!(0.0)),
        ("xtc_probability", json!(0.0)),
        ("dynatemp_range", json!(0.0)),
        ("mirostat", json!(0)),
        ("ignore_eos", json!(false)),
        // A stop string such as "\n\n" would end the summary after one paragraph.
        ("stop_strings", json!("[]")),
        ("grammar", json!("")),
    ];
    for (k, v) in set.drain(..) {
        if has(k) {
            s.set(k, v);
        }
    }
    s
}

// ------------------------------------------------------------------ network

pub fn client() -> Result<reqwest::Client> {
    reqwest::Client::builder()
        .connect_timeout(Duration::from_secs(10))
        .build()
        .context("building HTTP client")
}

fn authed(rb: reqwest::RequestBuilder, c: &Connection) -> reqwest::RequestBuilder {
    if c.api_key.trim().is_empty() {
        rb
    } else {
        rb.bearer_auth(c.api_key.trim())
    }
}

fn status_hint(status: reqwest::StatusCode) -> &'static str {
    match status.as_u16() {
        401 | 403 => " (check the API key)",
        503 => " (the server may still be loading the model)",
        _ => "",
    }
}

/// Everything needed to send one generation, built from a connection.
pub struct DirectRequest {
    pub conn: Connection,
    pub body: Value,
    pub stream: bool,
}

/// Build the request for `prompt` (already formatted) with the connection's settings.
pub fn build_request(c: &Connection, prompt: &str, stop: &[String]) -> Result<DirectRequest> {
    let p = c
        .provider()
        .ok_or_else(|| anyhow!("connection '{}' has an unknown kind '{}'", c.name, c.kind))?;
    if c.url.trim().is_empty() {
        bail!("connection '{}' has no address; set it with `/api`", c.name);
    }
    let params = c.resolved();
    Ok(DirectRequest {
        conn: c.clone(),
        body: p.build_body(&params, prompt, stop),
        stream: p.streaming(&params),
    })
}

/// Send the request and report the reply as `GenEvent`s.
pub async fn run(req: DirectRequest, id: u64, tx: UnboundedSender<GenMsg>) {
    let ev = match run_inner(&req, id, &tx).await {
        Ok(()) => GenEvent::Done,
        Err(e) => GenEvent::Error(format!("{:#}", e)),
    };
    let _ = tx.send((id, ev));
}

async fn run_inner(req: &DirectRequest, id: u64, tx: &UnboundedSender<GenMsg>) -> Result<()> {
    let p = req
        .conn
        .provider()
        .ok_or_else(|| anyhow!("unknown connection kind '{}'", req.conn.kind))?;
    let url = format!("{}{}", req.conn.base(), p.generate_path());
    let http = client()?;
    let mut resp = authed(http.post(&url), &req.conn)
        .json(&req.body)
        .send()
        .await
        .with_context(|| format!("could not reach {} at {}", p.label(), req.conn.base()))?;

    let status = resp.status();
    if !status.is_success() {
        let text = resp.text().await.unwrap_or_default();
        let detail = serde_json::from_str::<Value>(&text)
            .ok()
            .and_then(|v| p.error_in(&v))
            .unwrap_or_else(|| short(&text, 300));
        bail!("{}: {} ({}){}", p.label(), detail, status, status_hint(status));
    }

    if !req.stream {
        let text = resp.text().await.context("reading response")?;
        let v: Value = serde_json::from_str(&text)
            .with_context(|| format!("unexpected response: {}", short(&text, 200)))?;
        if let Some(e) = p.error_in(&v) {
            bail!("{}", e);
        }
        let out = p.parse_full(&v).unwrap_or_default();
        if out.is_empty() {
            bail!("the model returned an empty response");
        }
        let _ = tx.send((id, GenEvent::Chunk(out)));
        return Ok(());
    }

    let mut buf: Vec<u8> = Vec::new();
    let mut done = false;
    while !done {
        let chunk = resp.chunk().await.context("stream interrupted")?;
        let Some(chunk) = chunk else { break };
        buf.extend_from_slice(&chunk);
        while let Some(pos) = buf.iter().position(|b| *b == b'\n') {
            let line_bytes: Vec<u8> = buf.drain(..=pos).collect();
            let line = String::from_utf8_lossy(&line_bytes).trim().to_string();
            match p.parse_stream_line(&line) {
                Piece::Text(t) => {
                    let _ = tx.send((id, GenEvent::Chunk(t)));
                }
                Piece::Done => {
                    done = true;
                    break;
                }
                Piece::Error(e) => bail!("{}", e),
                Piece::Skip => {}
            }
        }
    }
    if !done && !buf.is_empty() {
        let line = String::from_utf8_lossy(&buf).trim().to_string();
        match p.parse_stream_line(&line) {
            Piece::Text(t) => {
                let _ = tx.send((id, GenEvent::Chunk(t)));
            }
            Piece::Error(e) => bail!("{}", e),
            _ => {}
        }
    }
    Ok(())
}

/// Ask the backend whether it is up and what it has loaded.
pub async fn probe(c: &Connection) -> Result<Info> {
    let p = c
        .provider()
        .ok_or_else(|| anyhow!("unknown connection kind '{}'", c.kind))?;
    if c.url.trim().is_empty() {
        bail!("no address set");
    }
    let http = client()?;
    let mut last: Option<anyhow::Error> = None;
    for path in p.info_paths() {
        let url = format!("{}{}", c.base(), path);
        let resp = match authed(http.get(&url), c)
            .timeout(Duration::from_secs(10))
            .send()
            .await
        {
            Ok(r) => r,
            // Not reachable at all: another path will not help.
            Err(e) => bail!("could not reach {}: {}", c.base(), e),
        };
        let status = resp.status();
        let text = resp.text().await.unwrap_or_default();
        if !status.is_success() {
            let detail = serde_json::from_str::<Value>(&text)
                .ok()
                .and_then(|v| p.error_in(&v))
                .unwrap_or_else(|| short(&text, 120));
            last = Some(anyhow!("{} returned {}{}: {}", path, status, status_hint(status), detail));
            continue;
        }
        let v: Value = serde_json::from_str(&text).unwrap_or(Value::Null);
        return Ok(p.parse_info(&v));
    }
    Err(last.unwrap_or_else(|| anyhow!("no answer from {}", c.base())))
}

/// `tarpi connect` (without `--local-api`): the host of the machine that runs
/// `tarpi serve`. A shared connection whose address is `127.0.0.1`,
/// `localhost` or `0.0.0.0` means "this machine" to the one that wrote it, so
/// here it is read as that host instead (same port).
static REMOTE_HOST: std::sync::OnceLock<String> = std::sync::OnceLock::new();

/// `serve_base` is the server's address as `tarpi connect` uses it
/// (`http://192.168.1.20:7878`); only its host is kept.
pub fn set_remote_host(serve_base: &str) {
    if let Some((host, _)) = split_host(serve_base) {
        let _ = REMOTE_HOST.set(host);
    }
}

/// `(host, rest)` of `scheme://host[:port]/path`: the host without its port
/// (an IPv6 host keeps its brackets) and everything after it.
fn split_host(url: &str) -> Option<(String, String)> {
    let (scheme, after) = url.split_once("://")?;
    let end = after.find('/').unwrap_or(after.len());
    let (auth, path) = after.split_at(end);
    let (host, port) = if auth.starts_with('[') {
        let close = auth.find(']')?;
        (&auth[..=close], &auth[close + 1..])
    } else {
        match auth.rfind(':') {
            Some(i) => (&auth[..i], &auth[i..]),
            None => (auth, ""),
        }
    };
    Some((host.to_string(), format!("{}://{{}}{}{}", scheme, port, path)))
}

fn is_this_machine(host: &str) -> bool {
    let h = host.trim_matches(|c| c == '[' || c == ']').to_lowercase();
    h == "localhost" || h == "0.0.0.0" || h == "::" || h == "::1" || h.starts_with("127.")
}

/// `url` with a loopback / unspecified host replaced by `host`.
fn with_remote_host(url: &str, host: &str) -> String {
    match split_host(url) {
        Some((h, template)) if is_this_machine(&h) => template.replacen("{}", host, 1),
        _ => url.to_string(),
    }
}

/// `tarpi connect` (without `--local-api`): the server (address, token) whose
/// backend does the tokenizing, because the connection's own address (often
/// `127.0.0.1:8080`) belongs to the machine that runs `tarpi serve`.
static REMOTE_TOKENIZER: std::sync::OnceLock<(String, String)> = std::sync::OnceLock::new();

pub fn set_remote_tokenizer(base: String, token: String) {
    let _ = REMOTE_TOKENIZER.set((base, token));
}

/// Ask `tarpi serve` to count `text` with its backend. `None` when that
/// server does not know the route (an older tarpi): count directly instead.
async fn remote_count(base: &str, token: &str, c: &Connection, text: &str) -> Result<Option<usize>> {
    let url = format!("{}/v1/tokenize", base);
    let mut rb = client()?
        .post(&url)
        .timeout(Duration::from_secs(60))
        .json(&json!({ "text": text, "connection": c.name }));
    if !token.is_empty() {
        rb = rb.bearer_auth(token);
    }
    let resp = rb.send().await.with_context(|| format!("POST {}", url))?;
    let status = resp.status();
    if status == reqwest::StatusCode::NOT_FOUND || status == reqwest::StatusCode::METHOD_NOT_ALLOWED {
        return Ok(None);
    }
    let body = resp.text().await.unwrap_or_default();
    if !status.is_success() {
        bail!("{} returned {}: {}", url, status, short(&body, 200));
    }
    let v: Value = serde_json::from_str(&body).with_context(|| format!("invalid JSON from {}", url))?;
    v.get("tokens")
        .and_then(|n| n.as_u64())
        .map(|n| Some(n as usize))
        .ok_or_else(|| anyhow!("{} gave no token count", url))
}

/// Exact token count of `text` from the backend's own tokenizer (the serving
/// machine's, under `tarpi connect`).
pub async fn count_tokens(c: &Connection, text: &str) -> Result<usize> {
    if let Some((base, token)) = REMOTE_TOKENIZER.get() {
        if let Some(n) = remote_count(base, token, c, text).await? {
            return Ok(n);
        }
    }
    let p = c
        .provider()
        .ok_or_else(|| anyhow!("unknown connection kind '{}'", c.kind))?;
    let (path, body) = p.tokenize_request(text);
    let url = format!("{}{}", c.base(), path);
    let http = client()?;
    let resp = authed(http.post(&url), c)
        .timeout(Duration::from_secs(60))
        .json(&body)
        .send()
        .await
        .with_context(|| format!("POST {}", url))?;
    let status = resp.status();
    let text = resp.text().await.unwrap_or_default();
    if !status.is_success() {
        bail!("{} returned {}: {}", url, status, short(&text, 200));
    }
    let v: Value =
        serde_json::from_str(&text).with_context(|| format!("invalid JSON from {}", url))?;
    p.parse_token_count(&v)
        .ok_or_else(|| anyhow!("{} gave no token count", url))
}

#[cfg(test)]
mod remote_host_tests {
    use super::*;

    #[test]
    fn this_machine_becomes_the_serve_host() {
        assert_eq!(with_remote_host("http://0.0.0.0:8080", "192.168.1.20"), "http://192.168.1.20:8080");
        assert_eq!(with_remote_host("http://127.0.0.1:8080", "192.168.1.20"), "http://192.168.1.20:8080");
        assert_eq!(with_remote_host("http://localhost:8080/x", "pc.local"), "http://pc.local:8080/x");
        assert_eq!(with_remote_host("http://[::1]:8080", "192.168.1.20"), "http://192.168.1.20:8080");
        assert_eq!(with_remote_host("http://localhost", "pc.local"), "http://pc.local");
    }

    #[test]
    fn other_hosts_are_left_alone() {
        assert_eq!(with_remote_host("http://10.0.0.5:8080", "192.168.1.20"), "http://10.0.0.5:8080");
        assert_eq!(with_remote_host("https://api.example.com", "192.168.1.20"), "https://api.example.com");
    }

    #[test]
    fn host_of_the_serve_address() {
        assert_eq!(split_host("http://192.168.1.20:7878").unwrap().0, "192.168.1.20");
        assert_eq!(split_host("http://[fe80::1]:7878").unwrap().0, "[fe80::1]");
    }
}
